<script lang="ts">import { BarChart, type BarChartBar } from '@microcks/deep-ink';const RUNS = Array.from({ length: 20 }, (_, i) => { const id = String(100 + i); const failed = i % 6 === 4; const ms = 700 + ((i * 337) % 1900); return { id, failed, ms }; }); let id = $state('119'); const bars = RUNS.map((r, i): BarChartBar => ({ id: r.id, value: r.ms, tone: r.failed ? 'danger' : 'success', label: i === 0 || i === RUNS.length - 1 || Number(r.id) % 5 === 0 ? r.id : '', description: `Run #${r.id}, ${r.failed ? 'failed' : 'passed'}, ${r.ms} ms` }));</script><div style="max-width:900px"><BarChart label="Runs, oldest to newest. Use the arrow keys to move between bars." {bars} max={3000} selectedId={id} onselect={v => id = v} ticks={['3 s','1.5 s','0']} table={{ caption: 'Last 20 runs, oldest first', columns: ['Run','Result','Duration'], rows: RUNS.map(r => [`#${r.id}`, r.failed ? 'Failed' : 'Passed', `${r.ms} ms`]) }}/></div>
